/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_198_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '113'); } }, { id: "c_when_199_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '111'); } }, { id: "c_when_200_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '121'); } }, { id: "c_when_201_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '131'); } }, { id: "c_when_202_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '141'); } }, { id: "c_when_203_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '151'); } }, { id: "if_bndMktactTpCd", fn: function(){ return (((dma_pageContext.get("bndMktactTpCd") ?? "") === '141' || (dma_pageContext.get("bndMktactTpCd") ?? "") === '131') && ((dma_pageContext.get("flag") ?? "") === 'NEW' || (dma_pageContext.get("flag") ?? "") === 'PRE')); } }, { id: "c_when_280_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '113'); } }, { id: "c_otherwise_281", fn: function(){ return (!(((dma_pageContext.get("bndMktactTpCd") ?? "") === '113'))); } }, { id: "c_when_314", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) !== 'GB' && String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) !== 'MB'); } }, { id: "tr_315", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) !== 'GB' && String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) !== 'MB'); } }, { id: "c_otherwise_339", fn: function(){ return (!((String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) !== 'GB' && String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) !== 'MB'))); } }, { id: "c_when_353", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "c_otherwise_355", fn: function(){ return (!((String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'))); } }, { id: "c_when_376", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "c_when_456", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "c_otherwise_469", fn: function(){ return (!((String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'))); } }, { id: "if_bndMktactTpCd_2", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") !== '141'); } }, { id: "c_when_609", fn: function(){ return ((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })()) === 'GB035'); } }, { id: "tr_610", fn: function(){ return ((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })()) === 'GB035'); } }, { id: "c_otherwise_624", fn: function(){ return (!(((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })()) === 'GB035'))); } }, { id: "c_when_690", fn: function(){ return ((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })()) === 'GB035'); } }, { id: "c_otherwise_706", fn: function(){ return (!(((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })()) === 'GB035'))); } }, { id: "c_when_738", fn: function(){ return ((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })()) === 'GB035'); } }, { id: "c_otherwise_751", fn: function(){ return (!(((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })()) === 'GB035'))); } }, { id: "c_when_869", fn: function(){ return ((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })()) === 'GB035' && (dma_pageContext.get("bndMktactTpCd") ?? "") === '111'); } }, { id: "tr_870", fn: function(){ return ((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })()) === 'GB035' && (dma_pageContext.get("bndMktactTpCd") ?? "") === '111'); } }, { id: "c_when_877", fn: function(){ return ((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })()) === 'GB035' && (dma_pageContext.get("bndMktactTpCd") ?? "") === '113'); } }, { id: "tr_878", fn: function(){ return ((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })()) === 'GB035' && (dma_pageContext.get("bndMktactTpCd") ?? "") === '113'); } }, { id: "if_bndMktactTpCd_3", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '141' && ((dma_pageContext.get("flag") ?? "") === 'NEW' || (dma_pageContext.get("flag") ?? "") === 'PRE' || (dma_pageContext.get("flag") ?? "") === 'TEMP')); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_bndMktactTpCd", fn: function () { return String(String((dma_pageContext.get("bndMktactTpCd") ?? ""))); } },
        { childId: "ipt_princintCount", fn: function () { return String((Array.isArray(String(dma_ht.get("princintList"))) ? String(dma_ht.get("princintList")).length : String(dma_ht.get("princintList")).length)); } },
        { childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("bndMktactTpNm") ?? ""))) + " (비상장채권 상장전환)"; } },
        { childId: "__rb3", fn: function () { return "표준코드시스템에서 ESG채권(" + String(dma_result.get("sriBndApplTpNm")) + ")으로 등록됨."; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

