 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.header_cd =$c.util.getComponent('ipt_bndMktactTpCd').getValue(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf05001' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.v_str = '' + dma_result.get("curr_tp_cd") + '';
        scwin.v_int_pay_mth = '' + dma_result.get("int_pay_methd_cd") + '';
        scwin.v_int_set_std_int = '' + dma_result.get("intRtDecsnMiscBasIntNm") + '';
        scwin.v_c_std_int = '' + dma_result.get("coupnRtDecsnBasIntCd") + '';
        scwin.v_flag = String(((dma_pageContext.get("flag") ?? "")) == null ? '' : ((dma_pageContext.get("flag") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("flag") ?? "")) == null ? '' : ((dma_pageContext.get("flag") ?? "")));
        scwin.v_rdmp_mth = '' + dma_result.get("redmpt_methd_tp_cd") + '';
        scwin.v_div_rdmp_cd = '' + dma_result.get("splitRedmptTpCd") + '';
        scwin.v_str1 = '' + dma_result.get("regInstCd") + '';
        scwin.v_str2 = '' + dma_result.get("regInstNm") + '';
        scwin.setAttachChk = setAttachChk;
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_datefmt_cal_isuDd();
        scwin.init_datefmt_cal_procsReqDd();
        scwin.init_datefmt_cal_redmptDd();
        scwin.init_datefmt_cal_feeDepoSchdlDd();
        scwin.init_datefmt_cal_fstIntPayDd();
        scwin.init_datefmt_cal_saleDd();
        scwin.init_datefmt_cal_grtYdStrtDd();
        scwin.init_datefmt_cal_addYdStrtDd();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf05001.onpageload' });
    }
};

