scwin.clickCreditValuInstCd = function (inst_cd, type, frm, obj) {
    if (obj.checked) {
        if ($c.util.getComponent("dma_preDataCheckValuesReq").get("isurCd") !== 'GB035') {
            if (!($c.util.getComponent('ipt_asstSecutizTpCd_8').getValue() !== '')) {
                $("input[name='credit_valu_inst_cd" + type + "'").val(inst_cd);
                $("select[name='byinst_credit_valu_grd" + type + "'").attr("disabled", false);
                $("input[name='sf_valu_yn" + type + "'").attr("disabled", false);
                $("input[name='sf_valu_yn" + type + "'").prop("checked", true);
            } else {
                $("input[name='credit_valu_inst_cd" + type + "'").val(inst_cd);
                $("select[name='byinst_credit_valu_grd" + type + "'").attr("disabled", false);
                $("input[name='sf_valu_yn" + type + "'").attr("disabled", true);
                $("input[name='sf_valu_yn" + type + "'").prop("checked", false);
            }
        } else {
            $("input[name='credit_valu_inst_cd" + type + "'").val(inst_cd);
            $("select[name='byinst_credit_valu_grd" + type + "'").attr("disabled", false);
            $("input[name='sf_valu_yn" + type + "'").attr("disabled", true);
            $("input[name='sf_valu_yn" + type + "'").prop("checked", false);
        }
    } else {
        $("input[name='credit_valu_inst_cd" + type + "'").val("");
        $("select[name='byinst_credit_valu_grd" + type + "'").val("");
        $("select[name='byinst_credit_valu_grd" + type + "'").attr("disabled", true);
        $("input[name='sf_valu_yn" + type + "'").attr("disabled", true);
        $("input[name='sf_valu_yn" + type + "'").prop("checked", false);
    }
};

/**
 * @method
 * @name setRedmptDd
 * @description set Redmpt Dd 처리
 * @param {Object} obj 컴포넌트
 * @param {*} addYy addYy
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setRedmptDd = async function (obj, addYy) {
    const isuDd = Del_Hypen2(obj);
    if (isuDd == null || isuDd === "") {
        await $c.win.alert("발행일을 입력하시기 바랍니다.");
        $c.util.getComponent("cal_isuDd").focus();
        return;
    }
    const tmpYy = isuDd.substr(0, 4);
    const tmpMm = isuDd.substr(4, 2);
    const tmpDd = isuDd.substr(6, 2);
    const redmptYy = parseInt(tmpYy) + parseInt(addYy);
    mmCnt = new Array(12);
    mmCnt[1] = '31';
    mmCnt[3] = '31';
    mmCnt[4] = '30';
    mmCnt[5] = '31';
    mmCnt[6] = '30';
    mmCnt[7] = '31';
    mmCnt[8] = '31';
    mmCnt[9] = '30';
    mmCnt[10] = '31';
    mmCnt[11] = '30';
    mmCnt[12] = '31';
    if (scwin.isYunMonth(redmptYy)) {
        mmCnt[2] = '29';
    } else {
        mmCnt[2] = '28';
    }
    if (parseInt(tmpDd, 10) < mmCnt[parseInt(tmpMm,10)]) {
        $c.util.getComponent("cal_redmptDd").setValue(redmptYy + "-" + tmpMm + "-" + tmpDd);
    } else {
        $c.util.getComponent("cal_redmptDd").setValue(redmptYy + "-" + tmpMm + "-" + mmCnt[parseInt(tmpMm,10)]);
    }
};

/**
 * @method
 * @name isYunMonth
 * @description is Yun Month 처리
 * @param {*} strYear strYear
 * @returns {void}
 * @hidden N
 */
scwin.isYunMonth = function (strYear) {
    nYear = parseInt(strYear);
    if ((nYear % 4) === 0) {
        return true;
    } else {
        return false;
    }
};

