            $("select#byinst_credit_valu_grd" + i).append("<option value='D'>D</option>");
        }
    } else {
        for (let i = 1; i < 5; i++) {
            $("select#byinst_credit_valu_grd" + i).append("<option value=''></option>");
            $("select#byinst_credit_valu_grd" + i).append("<option value='AAA'>AAA</option>");
            $("select#byinst_credit_valu_grd" + i).append("<option value='AA+'>AA+</option>");
